:root { font-family: system-ui, sans-serif; color: #182c40; background: #f4f7fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border-radius: 12px; box-shadow: 0 4px 24px #182c4010; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.form-controls { display: flex; gap: 12px; }
input { min-width: 0; flex: 1; padding: 10px; border: 1px solid #798b9e; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; color: white; background: #215fc0; font: inherit; cursor: pointer; }
button:hover { background: #194b9a; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #dd8c00; outline-offset: 3px; }
#projects, #tasks { list-style: none; padding: 0; margin-top: 28px; }
#projects li, #tasks li { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-bottom: 1px solid #dde4ec; }
#projects span { overflow-wrap: anywhere; min-width: 0; }
#projects button { flex-shrink: 0; }
[role="alert"] { color: #a11c28; }
#back { margin-bottom: 24px; }
select { padding: 10px; border: 1px solid #798b9e; border-radius: 6px; font: inherit; background: white; }
#tasks label { display: flex; align-items: center; gap: 12px; margin: 0; font-weight: normal; min-width: 0; }
#tasks input { flex: none; width: 20px; height: 20px; }
#tasks span { overflow-wrap: anywhere; min-width: 0; }
@media (max-width: 600px) { main { margin: 16px; padding: 20px; } .form-controls { flex-direction: column; } }

